 * Name: esp32s3_cam_dvp_capture
 *
 * Capture one complete RGB565 frame (vs_eof=1: VSYNC-driven EOF = frame
 * complete).  The GDMA ISR re-arms the chain at every frame boundary, so
 * the DMA always captures exactly one aligned frame per VSYNC.
 *
 * Flow:
 *   1. align  — wait for one EOF with the ISR active (guarantees the DMA
 *               is mid-capture of a complete frame when we mask below)
 *   2. mask   — disable the GDMA EOF interrupt + clear pending bits, so
 *               the ISR cannot re-arm (and overwrite) the frame we read
 *   3. wait   — for the next (post-mask) EOF; the DMA stops at this frame
 *               boundary with one complete frame in rxbuf
 *   4. freeze — esp32s3_dma_disable (already stopped at EOF, safety)
 *   5. sink   — optional RGB565 byte swap, then hand frame to the sink
 *   6. re-arm — cam_dvp_arm() + re-enable both interrupts for next capture
 *
 * Input Parameters:
 *   sink     - frame callback (called once with CAM_FRAME_SIZE bytes)
 *   sink_arg - opaque arg passed to sink
 *   eoi_out  - set to true when the frame is delivered (may be NULL)
 *
 * Returned Value: CAM_FRAME_SIZE on success; negated errno on failure.
 ****************************************************************************/

int esp32s3_cam_dvp_capture(void (*sink)(const uint8_t *data, size_t len,
                                          void *arg),
                            void *sink_arg,
                            volatile bool *eoi_out)
{
  struct esp32s3_cam_s *priv = &g_cam;
  int ch = priv->dma_channel;
  irqstate_t flags;
  uint32_t seen;
  uint32_t stall = 0;
  uint32_t regval;
  uint32_t raww;

  if (sink == NULL && eoi_out == NULL)
    {
      return -EINVAL;
    }

  printf("[Cam-DVP] capture enter (vs_eof=1): block_done=%u vsync=%u\n",
         priv->block_done, priv->vsync_count);

  /* 1. Align: wait for the next EOF with the ISR active.  The ISR re-arms
   *    the chain at every frame boundary, so afterwards the DMA is
   *    capturing one full frame per VSYNC (the first window after any
   *    cam_dvp_arm() is partial and self-heals at its EOF). */

  seen = priv->block_done;
  stall = 0;
  while (priv->block_done == seen)
    {
      up_udelay(2000);
      stall++;
      if ((stall % 500) == 0)
        {
          printf("[Cam-DVP] align wait... stall=%u\n", stall);
        }

      if (stall > 5000)
        {
          printf("[Cam-DVP] align timeout, no EOF\n");
          return -ETIMEDOUT;
        }
    }

  printf("[Cam-DVP] aligned (block_done=%u)\n", priv->block_done);

  /* 2. Mask the GDMA EOF interrupt and clear any pending EOF, so no ISR
   *    re-arm can overwrite the frame while we read it. */

  flags = enter_critical_section();

  regval = cam_dvp_getreg(cam_gdma_reg(DMA_IN_INT_ENA_CH0_REG, ch));
  regval &= ~DMA_IN_SUC_EOF_CH0_INT_ENA_M;
  cam_dvp_putreg(cam_gdma_reg(DMA_IN_INT_ENA_CH0_REG, ch), regval);

  cam_dvp_putreg(cam_gdma_reg(DMA_IN_INT_CLR_CH0_REG, ch),
                 DMA_IN_SUC_EOF_CH0_INT_ST_M);

  leave_critical_section(flags);

  /* 3. Wait for the NEXT (post-mask) EOF: the DMA stops at this frame
   *    boundary with one complete frame in rxbuf (it was capturing from
   *    the last ISR re-arm at the previous boundary). */

  stall = 0;
  for (;;)
    {
      raww = cam_dvp_getreg(cam_gdma_reg(DMA_IN_INT_RAW_CH0_REG, ch));
      if (raww & DMA_IN_SUC_EOF_CH0_INT_ST_M)
        {
          break;
        }

      up_udelay(2000);
      stall++;
      if ((stall % 500) == 0)
        {
          printf("[Cam-DVP] waiting frame EOF... stall=%u\n", stall);
        }

      if (stall > 5000)
        {
          printf("[Cam-DVP] frame EOF timeout\n");
          return -ETIMEDOUT;
        }
    }

  cam_dvp_putreg(cam_gdma_reg(DMA_IN_INT_CLR_CH0_REG, ch),
                 DMA_IN_SUC_EOF_CH0_INT_ST_M);

  /* 4. Freeze the DMA (it stopped at the EOF; belt & suspenders) */

  esp32s3_dma_disable(priv->dma_channel, false);

  /* 5. Optional RGB565 byte swap (sensor sends high byte first, LVGL
   *    wants little-endian), then hand the frame to the sink. */

  if (g_cam_byte_swap)
    {
      cam_swap_rgb565(g_cam_rxbuf, CAM_FRAME_SIZE);
    }

  printf("[Cam-DVP] frame done: %u bytes (swap=%s)\n",
         (unsigned)CAM_FRAME_SIZE, g_cam_byte_swap ? "on" : "off");

  if (sink != NULL)
    {
      int k;
      const uint8_t *fp = g_cam_rxbuf;

      printf("[Cam-DVP] frame head:");
      for (k = 0; k < 16; k++)
        {
          printf(" %02x", fp[k]);
        }

      printf("\n");

      cam_diag_pixels(fp, 0);
      cam_diag_pixels(fp, 320);
      cam_diag_pixels(fp, 16000);

      sink(g_cam_rxbuf, CAM_FRAME_SIZE, sink_arg);
    }

  /* 6. Re-arm for the next capture (cam_reset inside arm clears the
   *    LCD_CAM INT_ENA, so both interrupts are re-enabled afterwards). */

  cam_dvp_arm();
  cam_dvp_enable_ints();

  if (eoi_out != NULL)
    {
      *eoi_out = true;
    }

  printf("[Cam-DVP] capture done\n");
  return (int)CAM_FRAME_SIZE;
}", "old_string": "/****************************************************************************
 * Name: esp32s3_cam_dvp_capture
 *
 * Capture one complete RGB565 frame (vs_eof=0: EOF per 4092B block).
 * The first frame after arming is discarded (may start mid-frame), the
 * next frame is delivered to the sink as a single CAM_FRAME_SIZE chunk.
 *
 * Input Parameters:
 *   sink     - frame callback (called once with CAM_FRAME_SIZE bytes)
 *   sink_arg - opaque arg passed to sink
 *   eoi_out  - set to true when the frame is delivered (may be NULL)
 *
 * Returned Value: CAM_FRAME_SIZE on success; negated errno on failure.
 ****************************************************************************/

int esp32s3_cam_dvp_capture(void (*sink)(const uint8_t *data, size_t len,
                                          void *arg),
                            void *sink_arg,
                            volatile bool *eoi_out)
{
  struct esp32s3_cam_s *priv = &g_cam;
  uint32_t seen;
  uint32_t stall = 0;
  uint32_t total = 0;

  if (sink == NULL && eoi_out == NULL)
    {
      return -EINVAL;
    }

  printf("[Cam-DVP] capture enter (vs_eof=1): block_done=%u\n",
         priv->block_done);

  /* Official dvp_spi_lcd model: vs_eof=1, VSYNC triggers in_suc_eof =
   * frame COMPLETE (data already in DMA buffer).  Each EOF = one full
   * 38400B frame.  Skip the first frame (stream alignment), take the
   * next complete frame.  No byte swap: official 8-bit RGB565 does not
   * swap (byte_swap not supported for 8-bit data). */

  seen = priv->block_done;

  /* Wait for the first EOF (discard frame 1) */

  while (priv->block_done == seen)
    {
      up_udelay(2000);
      stall++;
      if ((stall % 500) == 0)
        {
          printf("[Cam-DVP] waiting first frame... stall=%u\n", stall);
        }

      if (stall > 5000)
        {
          printf("[Cam-DVP] first frame timeout, no data\n");
          return -ETIMEDOUT;
        }
    }

  printf("[Cam-DVP] frame 1 done (discard)\n");
  seen = priv->block_done;

  /* Wait for the second (valid) frame */

  stall = 0;
  while (priv->block_done == seen)
    {
      up_udelay(2000);
      stall++;
      if ((stall % 500) == 0)
        {
          printf("[Cam-DVP] waiting valid frame... stall=%u\n", stall);
        }

      if (stall > 5000)
        {
          printf("[Cam-DVP] valid frame timeout\n");
          return -ETIMEDOUT;
        }
    }

  /* Freeze DMA so the frame is stable */

  esp32s3_dma_disable(priv->dma_channel, false);

  total = CAM_FRAME_SIZE;

  printf("[Cam-DVP] frame done: %u bytes\n", (unsigned)total);

  if (sink != NULL)
    {
      int k;
      const uint8_t *fp = g_cam_rxbuf;

      printf("[Cam-DVP] frame head:");
      for (k = 0; k < 16; k++)
        {
          printf(" %02x", fp[k]);
        }

      printf("\n");

      sink(g_cam_rxbuf, CAM_FRAME_SIZE, sink_arg);
    }

  /* Re-arm for the next frame (ll_cam_start) */

  cam_dvp_arm();

  if (eoi_out != NULL)
    {
      *eoi_out = true;
    }

  printf("[Cam-DVP] capture done: %u bytes\n", (unsigned)total);
  return (int)total;
}"}

