{"file_path": "/home/vboxuser/openvela/apps/plant-companion/main/app_main.c", "new_string": "/****************************************************************************
 * Name: lcd_put_rgb565
 *
 * 直接写 LCD（绕过 LVGL 渲染器）：软件最近邻缩放 RGB565 帧 → LCDDEVIO_PUTAREA。
 *
 * 背景：本 LVGL 版本的 lv_image 渲染 RGB565 有 bug（缩放上半错乱、对象
 * 删除后区域不重绘导致"蓝白色残留遮挡"），摄像头/测试图改用直接写屏。
 * 数据为小端 RGB565（st7789 驱动内部会转成大端送给面板）。
 *
 * 输入：fb=源帧(sw×sh×2 小端), 目标区域 (dx,dy,dw,dh)。
 * 逐行缩放 + ioctl 写一行，内存占用仅一行缓冲。
 ****************************************************************************/

static int lcd_put_rgb565(const uint8_t *fb, int sw, int sh,
                          int dx, int dy, int dw, int dh)
{
  int fd = open("/dev/lcd0", O_WRONLY);
  uint8_t rowbuf[960];      /* 一行目标（最大 480 像素 × 2B） */
  struct lcddev_area_s area;
  int y;

  if (fd < 0)
    {
      printf("[LCD] open /dev/lcd0 failed: %d\n", fd);
      return -1;
    }

  if (dw > 480)
    {
      dw = 480;
    }

  memset(&area, 0, sizeof(area));
  area.col_start = dx;
  area.col_end = dx + dw - 1;
  area.stride = 0;

  for (y = 0; y < dh; y++)
    {
      int sy = (y * sh) / dh;    /* 最近邻：目标行 → 源行 */
      int x;

      if (sy >= sh)
        {
          sy = sh - 1;
        }

      for (x = 0; x < dw; x++)
        {
          int sx = (x * sw) / dw;

          if (sx >= sw)
            {
              sx = sw - 1;
            }

          rowbuf[x * 2]     = fb[sy * sw * 2 + sx * 2];
          rowbuf[x * 2 + 1] = fb[sy * sw * 2 + sx * 2 + 1];
        }

      area.row_start = dy + y;
      area.row_end = dy + y;
      area.data = rowbuf;
      ioctl(fd, LCDDEVIO_PUTAREA, (unsigned long)&area);
    }

  close(fd);
  return 0;
}

