static int lcd_put_rgb565(const uint8_t *fb, int sw, int sh,
                          int dx, int dy, int dw, int dh)
{
  int fd = open("/dev/lcd0", O_WRONLY);
  uint8_t rowbuf[960];      /* 一行目标（最大 480 像素 × 2B） */
  struct lcddev_area_s area;
  int y;

  if (fd < 0)
    {
      printf("[LCD] open /dev/lcd0 failed: %d\n", fd);
      return -1;
    }

  if (dw > 480)
    {
      dw = 480;
    }

  memset(&area, 0, sizeof(area));
  area.col_start = dx;
  area.col_end = dx + dw - 1;
  area.stride = 0;

  for (y = 0; y < dh; y++)
    {
      int sy = (y * sh) / dh;    /* 最近邻：目标行 → 源行 */
      int x;

      if (sy >= sh)
        {
          sy = sh - 1;
        }

      for (x = 0; x < dw; x++)
        {
          int sx = (x * sw) / dw;

          if (sx >= sw)
            {
              sx = sw - 1;
            }

          rowbuf[x * 2]     = fb[sy * sw * 2 + sx * 2];
          rowbuf[x * 2 + 1] = fb[sy * sw * 2 + sx * 2 + 1];
        }

      area.row_start = dy + y;
      area.row_end = dy + y;
      area.data = rowbuf;
      ioctl(fd, LCDDEVIO_PUTAREA, (unsigned long)&area);
    }

  close(fd);
  return 0;
}

