{
  s_preview_freeze = false;
  return 0;
}

int camera_preview_stop(void)
{
  if (!s_preview_run)
    {
      return 0;
    }

  s_preview_run = false;
  pthread_join(s_preview_tid, NULL);
  s_preview_tid = 0;
  return 0;
}
