 * 双缓冲避免"渲染中帧被覆盖"撕裂。 */

static uint8_t s_preview_buf[2][38400] __attribute__((aligned(4)));
static volatile int s_preview_cur;      /* 正在写入的缓冲 */
static volatile int s_preview_latest;   /* 最新完整帧的缓冲索引 */

static void *camera_preview_loop(void *arg)
{
  volatile bool eoi = false;
  int ret;

  (void)arg;

  /* OV3660 RGB565 小端输出：强制不交换（防任何残留/误设） */

  esp32s3_cam_dvp_set_swap(false);
