      ret = esp32s3_cam_dvp_capture(NULL, NULL, &eoi);
      if (ret < 0)
        {
          break;
        }

      /* 拷入当前缓冲（rxbuf 在 capture 返回后稳定），切换 latest */

      memcpy(s_preview_buf[s_preview_cur],
