static pthread_t s_preview_tid;
static volatile bool s_preview_run;
static volatile bool s_preview_freeze;

/* 预览：capture 完成后 rxbuf 稳定（驱动 capture 末尾不 re-arm），
 * 直接软件缩放写 LCD 取景框区域（LCDDEVIO_PUTAREA，已验证颜色正确）。
 * 取景框内部无 LVGL 对象（UI 侧已清空），LVGL 不会 invalidate 该区域，
