{"file_path": "/home/vboxuser/openvela/apps/plant-companion/ui/screens/screen_camera.c", "content": "/****************************************************************************
 * apps/plant-companion/ui/screens/screen_camera.c
 *
 * ② AI拍照 — 植物识别
 *   顶部：返回 + 「拍一拍」
 *   中部：取景框（绿色边框 + 中央盆栽占位图标 + 扫描线动画）
 *   底部：提示「把植物放在框框里哦~」+ 拍照按钮
 *
 * 3C-2：拍照 → ai_service 异步诊断（后台线程跑 ai_engine，不卡 UI）。
 *   当前无摄像头帧采集驱动，先以演示数据填充；OV3660 帧采集接入后
 *   替换 jpeg 数据源即可。完成回调投递到 ui_task 刷新诊断页。
 ****************************************************************************/

#include <lvgl/lvgl.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#include "screen_camera.h"
#include "screen_diagnose.h"
#include "../ui_app.h"
#include "../theme/theme_plant.h"

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
#  include "../../components/camera_capture/camera_capture.h"
#endif

#ifdef CONFIG_PLANT_AI_MODULE
#  include "../../services/ai_service.h"
#endif

/****************************************************************************
 * Private Data
 ****************************************************************************/

static lv_obj_t *s_scanline;
static lv_anim_t s_scan_anim;
static lv_obj_t *s_status_label;   /* 「AI识别中…」状态文字 */

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
/* 预览帧显示：LVGL lv_image 引用预览双缓冲（camera_preview_get_frame）。
 * LVGL 统一渲染写屏（无并行写 LCD），避免花屏/污染 UI。 */
#define CAM_VIEW_W     160
#define CAM_VIEW_H     120
#define CAM_VIEW_SIZE  (CAM_VIEW_W * CAM_VIEW_H * 2)

static lv_obj_t *s_cam_image;
static lv_image_dsc_t s_cam_img_dsc;
static lv_timer_t *s_preview_timer;   /* 预览帧刷新定时器（ui_task 上下文） */
static bool s_cam_configured;   /* OV3660 RGB565 已配置（避免每次重配） */
#endif

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void cam_on_back(lv_event_t *e)
{
  (void)e;
  ui_app_pop_screen();
}

/* AI 完成回调（ai 工作线程触发）：把诊断数据带到 ui_task 上下文 */

static void cam_ai_done(void *user_data,
                        const struct ai_service_result_s *result)
{
  lv_obj_t *diag;
  const char *name;
  char tags[64];
  char issue_desc[128];
  char advice[256];
  bool has_issue;
  (void)user_data;

#ifdef CONFIG_PLANT_AI_MODULE
  if (result != NULL && result->success)
    {
      name = (result->engine.image.disease[0] != '\0') ?
             result->engine.image.disease : "识别成功";

      snprintf(tags, sizeof(tags), "#植物 #诊断 #养护");
      snprintf(issue_desc, sizeof(issue_desc), "%s",
               result->engine.image.advice[0] != '\0' ?
               result->engine.image.advice : "看起来状态不错");
      snprintf(advice, sizeof(advice), "%s",
               result->engine.summary[0] != '\0' ?
               result->engine.summary : "继续保持哦~");
      has_issue = true;
    }
  else
#endif
    {
      /* 失败/AI未启用：回退演示数据（离线可演示） */

      name = "绿萝";
      snprintf(issue_desc, sizeof(issue_desc), "叶片有少量黄斑，可能是浇水过多");
      snprintf(advice, sizeof(advice), "建议：减少浇水频率，移到通风处");
      snprintf(tags, sizeof(tags), "#好养 #净化空气 #喜阴");
      has_issue = true;
    }

  /* 在 ui_task 上下文创建诊断页（LVGL 对象只能在 ui_task 操作） */

  diag = screen_diagnose_create();
  screen_diagnose_set(diag, name, "", 96, tags,
                      has_issue, issue_desc, advice);
  ui_app_push_screen(diag);

  if (s_status_label != NULL)
    {
      lv_label_set_text(s_status_label, "识别完成 ✓");
    }
}

/* 拍照：配置 OV3660 输出 JPEG → 捕获一帧 → 异步提交真实 MiMo 视觉诊断。
 * 帧采集（camera_capture_frame）当前为占位 -ENOSYS，DMA 收帧驱动
 * 完成后即走真实拍照链路；在此之前保留演示兜底。
 *
 * 内存策略：JPEG 帧缓冲在拍照瞬间才从堆上分配，提交给
 * ai_service（内部会拷贝一份给后台线程）后立即释放——拍完即擦，
 * 不常驻 .bss，也不把图片落盘（落盘/SD 卡等存储架构就绪后再做）。 */

#define CAMERA_JPEG_BUF_SIZE  (128 * 1024)   /* QVGA JPEG 上限保险值 */

static void cam_on_shoot(lv_event_t *e)
{
  (void)e;

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
  /* 手机相机式：预览已由后台线程持续显示（create 时启动），
   * 拍照 = 定格当前帧（预览线程冻结，画面保留在取景框） */

  if (s_status_label != NULL)
    {
      lv_label_set_text(s_status_label, "拍摄完成 ✓");
    }

  camera_preview_take();

  /* AI 识别（本地已捕获 RGB565；AI 服务器方案后续接入） */

#  ifdef CONFIG_PLANT_AI_MODULE
  cam_ai_done(NULL, NULL);   /* 演示诊断（AI 服务器接入后替换） */
#  endif

#else
  /* 摄像头未配置：演示诊断 */

  cam_ai_done(NULL, NULL);
#endif
}

/* 页面销毁（返回）：停止预览线程 + 删除刷新定时器 */

static void cam_on_delete(lv_event_t *e)
{
  (void)e;

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
  camera_preview_stop();

  if (s_preview_timer != NULL)
    {
      lv_timer_delete(s_preview_timer);
      s_preview_timer = NULL;
    }
#endif
}

/* LVGL 定时器：ui_task 上下文检测新预览帧 → 更新 lv_image → invalidate。
 * LVGL 统一渲染写屏，与预览线程（仅 memcpy 双缓冲）无 LCD 竞争。 */

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
static void preview_timer_cb(lv_timer_t *timer)
{
  static int s_last_idx = -1;
  int idx;
  (void)timer;

  idx = camera_preview_get_frame_index();

  if (idx != s_last_idx)
    {
      s_last_idx = idx;

      if (s_cam_image != NULL)
        {
          s_cam_img_dsc.data = camera_preview_get_frame();
          lv_image_set_src(s_cam_image, &s_cam_img_dsc);
          lv_obj_invalidate(s_cam_image);
        }
    }
}
#endif


static void scan_anim_cb(void *var, int32_t v)
{
  lv_obj_set_y((lv_obj_t *)var, (lv_coord_t)v);
}

static void scanline_start(lv_obj_t *viewport, lv_coord_t y0, lv_coord_t y1)
{
  lv_anim_init(&s_scan_anim);
  lv_anim_set_var(&s_scan_anim, s_scanline);
  lv_anim_set_exec_cb(&s_scan_anim, scan_anim_cb);
  lv_anim_set_values(&s_scan_anim, y0, y1);
  lv_anim_set_time(&s_scan_anim, 1400);
  lv_anim_set_playback_time(&s_scan_anim, 1400);
  lv_anim_set_repeat_count(&s_scan_anim, LV_ANIM_REPEAT_INFINITE);
  lv_anim_start(&s_scan_anim);
  (void)viewport;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

lv_obj_t *screen_camera_create(void)
{
  lv_obj_t *scr = lv_obj_create(lv_screen_active());
  lv_obj_t *back;
  lv_obj_t *title;
  lv_obj_t *viewport;
  lv_obj_t *hint;
  lv_obj_t *shoot;

  lv_obj_remove_style_all(scr);
  lv_obj_set_size(scr, 480, 320);
  lv_obj_set_style_bg_color(scr, lv_color_hex(0x0f172a), 0);
