  /* 顶部：返回 + 拍一拍 */

  back = lv_button_create(scr);
  lv_obj_remove_style_all(back);
  lv_obj_set_size(back, 96, TP_TOP_BAR_H);
  lv_obj_set_pos(back, 0, 0);
  lv_obj_set_style_text_color(back, lv_color_hex(0xffffff), 0);
  lv_obj_set_style_text_font(back, TP_FONT_BODY, 0);
  theme_btn_set_text(back, LV_SYMBOL_LEFT " 返回");
  lv_obj_add_event_cb(back, cam_on_back, LV_EVENT_CLICKED, NULL);

  title = lv_label_create(scr);
  lv_label_set_text(title, "拍一拍");
  lv_obj_set_style_text_font(title, TP_FONT_TITLE, 0);
  lv_obj_set_style_text_color(title, lv_color_hex(0xffffff), 0);
  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 8);

  lv_obj_t *ai_tag = lv_label_create(scr);
  lv_label_set_text(ai_tag, "AI识别中");
  lv_obj_set_style_text_font(ai_tag, TP_FONT_BODY, 0);
  lv_obj_set_style_text_color(ai_tag, lv_color_hex(TP_CLR_PRIMARY_GREEN_LIGHT), 0);
  lv_obj_align(ai_tag, LV_ALIGN_TOP_RIGHT, -12, 12);
  s_status_label = ai_tag;

  /* 取景框（占位：绿色边框区；3C-2 摄像头预览直写） */

  viewport = lv_obj_create(scr);
