  s_cam_image = lv_image_create(viewport);
  lv_obj_remove_style_all(s_cam_image);
  lv_obj_center(s_cam_image);

  /* 等比缩放填满取景框（420×190）；字节交换修复后 lv_image 渲染正常 */

  lv_image_set_scale(s_cam_image, LV_MIN(420 * 256 / CAM_VIEW_W,
                                         190 * 256 / CAM_VIEW_H));
  lv_obj_set_size(s_cam_image, CAM_VIEW_W * LV_MIN(420 * 256 / CAM_VIEW_W,
                        190 * 256 / CAM_VIEW_H) / 256,
                  CAM_VIEW_H * LV_MIN(420 * 256 / CAM_VIEW_W,
                        190 * 256 / CAM_VIEW_H) / 256);
  lv_obj_center(s_cam_image);

  s_cam_img_dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
  s_cam_img_dsc.header.cf = LV_COLOR_FORMAT_RGB565;
  s_cam_img_dsc.header.w = CAM_VIEW_W;
  s_cam_img_dsc.header.h = CAM_VIEW_H;
  s_cam_img_dsc.header.stride = CAM_VIEW_W * 2;
  s_cam_img_dsc.data_size = CAM_VIEW_SIZE;
