  /* 扫描线（静态装饰）：不启动动画 —— 动画会不断 invalidate 取景框区域，
   * 与预览线程直接写 LCD 竞争导致花屏/撕裂 */

  s_scanline = lv_obj_create(viewport);
  lv_obj_remove_style_all(s_scanline);
  lv_obj_set_size(s_scanline, 420, 3);
